<?php use Passport\Copy; use Passport\Rules; $restricted = $story['sensitivity'] === 'RESTRICTED'; ?>
<div class="passport-heading"><div><p class="eyebrow"><?= $e($t('A DECLARED STORY RECORD')) ?></p><h1><?= $e($story['title'] ?? $t('restricted')) ?></h1><p class="lead"><?= $e($story['creator']['name']) ?></p><span class="badge"><?= $e(Copy::STATUS[$story['status']]) ?></span><?php if ($restricted): ?> <span class="badge warning"><?= $e($t('Restricted')) ?></span><?php endif ?><p class="muted"><?= $e($t('Authority and identity are not independently verified.')) ?></p></div><div class="passport-stamp"><span><?= $e($t('STORY PASSPORT')) ?></span><strong class="mono"><?= $e($story['id']) ?></strong><time datetime="<?= $e($story['createdAt']) ?>" data-local-date><?= $e(substr($story['createdAt'], 0, 10)) ?></time></div></div>
<div class="passport-grid"><section class="card content-card"><?php if ($restricted): ?><div class="protected"><span aria-hidden="true">◈</span><h2><?= $e($t('Held with care.')) ?></h2><p><?= $e(Copy::RESTRICTED) ?></p></div><?php else: ?><p class="eyebrow"><?= $e($story['language']) ?><?= $story['placeCoarse'] ? ' · ' . $e($story['placeCoarse']) : '' ?></p><?php if ($story['mediaType'] === 'text'): ?><div class="story-text"><?= nl2br($e($story['textBody'])) ?></div><?php elseif ($story['mediaType'] === 'image'): ?><img class="story-image" src="<?= $e($story['mediaUrl']) ?>" alt="<?= $e($story['title']) ?>"><?php elseif ($story['mediaType'] === 'audio'): ?><audio controls preload="metadata" src="<?= $e($story['mediaUrl']) ?>"><?= $e($t('Your browser cannot play this audio.')) ?></audio><?php else: ?><video controls preload="metadata" src="<?= $e($story['mediaUrl']) ?>"><?= $e($t('Your browser cannot play this video.')) ?></video><?php endif ?><hr><h2><?= $e($t('Context from the steward')) ?></h2><p class="preserve"><?= $e($story['contextNote']) ?></p><h2><?= $e($t('What you can do with this story')) ?></h2><ul class="terms"><?php foreach (Rules::license($story['license']['preset'], $story['license']['aiTrainingAllowed']) as $line): ?><li><?= $e($line) ?></li><?php endforeach ?></ul><?php if ($story['license']['notes']): ?><p><?= $e($story['license']['notes']) ?></p><?php endif ?><hr><h2><?= $e($t('Consent, person by person')) ?></h2><?php foreach ($story['contributors'] as $person): ?><div class="consent-person"><h3><?= $e($person['name']) ?> <small><?= $e($person['role']) ?></small></h3><div class="consent-tags"><?php foreach (Copy::PURPOSES as $purpose => $label): $c = $person['consents'][$purpose] ?? null; ?><span class="badge <?= ($c['granted'] ?? false) ? '' : 'warning' ?>"><?= $e($label) ?> · <?= $e(($c['granted'] ?? false) ? $t('Granted') : $t('Not granted')) ?><?php if ($c): ?> <time datetime="<?= $e($c['recordedAt']) ?>" data-local-date><?= $e(substr($c['recordedAt'], 0, 10)) ?></time><?php endif ?></span><?php endforeach ?></div></div><?php endforeach ?><h2><?= $e($t('Declared revenue shares')) ?></h2><?php foreach ($story['shares'] as $share): $person = array_values(array_filter($story['contributors'], static fn(array $p): bool => $p['id'] === $share['contributorId']))[0]; ?><div class="share-row"><span><?= $e($person['name']) ?></span><strong><?= $e(number_format($share['bps'] / 100, 2)) ?>%</strong></div><?php endforeach ?><?php endif ?><p class="notice"><?= $e(Copy::LIMITS) ?></p></section>
<aside><section class="card qr-card"><img src="/api/stories/<?= $e($story['id']) ?>/qr" width="200" height="200" alt="<?= $e($t('QR code for this passport')) ?>"><h2><?= $e($t('Keep the record close.')) ?></h2><a href="/api/stories/<?= $e($story['id']) ?>/qr?download=1" download><?= $e($t('Download QR PNG')) ?> ↓</a><button class="text-button" type="button" data-print><?= $e($t('Print passport')) ?></button></section><section class="card"><h2><?= $e($t('Ask the steward')) ?></h2><p><?= $e($t('Use the permission form below, or contact the steward directly.')) ?></p><a href="mailto:<?= $e($story['contactEmail']) ?>"><?= $e($t('Contact steward')) ?> ↗</a></section></aside></div>
<div class="form-grid"><section class="card" id="permission"><p class="eyebrow"><?= $e($t('START A CONVERSATION')) ?></p><h2><?= $e($t('Request permission')) ?></h2><p><?= $e($t('Your contact details are shared with the steward, not published.')) ?></p><form data-api="/api/stories/<?= $e($story['id']) ?>/requests" data-success="requestSaved"><label><?= $e($t('Your name')) ?><input name="requesterName" required maxlength="200" autocomplete="name"></label><label><?= $e($t('Your email')) ?><input name="requesterContact" type="email" required maxlength="254" autocomplete="email"></label><label><?= $e($t('How would you use this story?')) ?><textarea name="intendedUse" required maxlength="4000"></textarea></label><label class="check"><input type="checkbox" name="isCommercial"> <?= $e($t('This is a commercial use')) ?></label><label class="check"><input type="checkbox" name="isAiTraining"> <?= $e($t('This involves AI or model training')) ?></label><div class="two"><label><?= $e($t('Proposed MOCK fee (minor units, optional)')) ?><input type="number" name="proposedFeeMinor" min="0" max="1000000000" step="1" data-int></label><label><?= $e($t('Currency')) ?><select name="currency"><?php foreach (['ZAR','USD','EUR','GBP','KES','NGN'] as $currency): ?><option><?= $e($currency) ?></option><?php endforeach ?></select></label></div><p class="muted"><?= $e($t('100 minor units = 1 currency unit. All fees and payments are MOCK.')) ?></p><button class="button"><?= $e($t('Send permission request')) ?></button><p class="form-message" role="status" aria-live="polite"></p></form></section>
<section class="card" id="claim"><p class="eyebrow"><?= $e($t('MAKE ROOM FOR OTHER VOICES')) ?></p><h2><?= $e($t('Report a conflicting claim')) ?></h2><p><?= $e($t('A registry entry can be questioned. Reports go privately to the steward for review.')) ?></p><form data-api="/api/stories/<?= $e($story['id']) ?>/claims" data-success="claimSaved"><label><?= $e($t('Your name')) ?><input name="reporterName" required maxlength="200"></label><label><?= $e($t('Your email')) ?><input name="reporterContact" type="email" required maxlength="254"></label><label><?= $e($t('What should the steward review?')) ?><textarea name="reason" required maxlength="4000"></textarea></label><button class="button secondary"><?= $e($t('Send report')) ?></button><p class="form-message" role="status" aria-live="polite"></p></form></section></div>
